// Superclass
class Vehicle {
    protected String brand = "Generic";

    public void start() {
        System.out.println("Vehicle is starting...");
    }
}

// Subclass extending Vehicle
class ElectricCar extends Vehicle {
    private int batteryCapacity;

    public ElectricCar(String brand, int battery) {
        this.brand = brand;
        this.batteryCapacity = battery;
    }

    @Override
    public void start() {
        System.out.println(brand + " EV powers up silently with " + batteryCapacity + "kWh battery.");
    }
}

public class MainApp {
    public static void main(String[] args) {
        // Polymorphic reference: superclass reference holding subclass object
        Vehicle v = new ElectricCar("Tesla", 85);
        v.start(); // Dynamic method dispatch executes ElectricCar's start()
    }
}

