class Animal {
    String category = "General Animal";

    Animal(String name) {
        System.out.println("Animal constructor called for: " + name);
    }

    void eat() {
        System.out.println("Animal is eating.");
    }
}

class Dog extends Animal {
    String category = "Canine"; // Shadows Animal's category

    Dog(String name) {
        super(name); // Explicitly invoke superclass constructor
    }

    void printCategories() {
        System.out.println("Subclass category: " + category);        // Canine
        System.out.println("Superclass category: " + super.category); // General Animal
    }

    @Override
    void eat() {
        super.eat(); // Invoke parent method
        System.out.println("Dog eats dog food.");
    }
}

